    var math = ClassDB.instantiate("FastVectorMath")

    # Test dot_product
    if is_equal_approx(math.dot_product(Vector3(1,0,0), Vector3(1,0,0)), 1.0):
        print("PASS: dot_product")

    # Test cross_product
    if math.cross_product(Vector3(1,0,0), Vector3(0,1,0)) == Vector3(0,0,1):
        print("PASS: cross_product")

    # Test centroid_and_bounds
    var points = PackedVector3Array([Vector3(0,0,0), Vector3(2,2,2)])
    var result = math.compute_centroid_and_bounds(points)
    if result[0] == Vector3(1,1,1) and result[1] == Vector3(0,0,0) and result[2] == Vector3(2,2,2):
        print("PASS: compute_centroid_and_bounds")

    # Test ray_sphere
    var dist = math.ray_sphere_intersection(Vector3(0,0,-5), Vector3(0,0,1), Vector3(0,0,0), 1.0)
    if is_equal_approx(dist, 4.0):
        print("PASS: ray_sphere_intersection")

    print("ALL TESTS PASSED")
    quit()
